-- Cloudy tenant queries (P4). Always run inside tenancy.Tx; every statement names team_id as
-- well, and the RLS policies in *_p4_row_level_security.sql hold when one is forgotten.

-- OpenApprovalRequest is the one-shot capability lookup AND the filer, in a single statement.
-- ON CONFLICT over approval_requests_open_key means a client retrying a refused destructive call
-- gets its own existing row back — pending (still refused) or approved (about to be burnt) —
-- instead of queueing a duplicate ask for the approver.
-- name: OpenApprovalRequest :one
INSERT INTO approval_requests (team_id, token_id, user_id, tool, resource_type, resource_name, args_summary, expires_at)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
ON CONFLICT (team_id, token_id, tool, resource_type, resource_name) WHERE status IN ('pending', 'approved')
DO UPDATE SET updated_at = now()
RETURNING *;

-- BurnApprovalRequest consumes an approved request. The WHERE clause is the whole gate: it only
-- matches a row that is still 'approved' and not expired, so two concurrent callers cannot both
-- win, and an approval can never authorise a second destructive call.
-- name: BurnApprovalRequest :one
UPDATE approval_requests
SET status = 'used', updated_at = now()
WHERE id = $1 AND team_id = $2 AND status = 'approved' AND expires_at > now()
RETURNING *;

-- name: DecideApprovalRequest :one
UPDATE approval_requests
SET status = $3, decided_by = $4, decided_at = now(), updated_at = now()
WHERE id = $1 AND team_id = $2 AND status = 'pending' AND expires_at > now()
RETURNING *;

-- name: ListApprovalRequestsOfTeam :many
SELECT * FROM approval_requests
WHERE team_id = $1 AND ($2::text = '' OR status = $2::text)
ORDER BY created_at DESC
LIMIT $3;

-- name: ApprovalRequestInTeam :one
SELECT * FROM approval_requests WHERE id = $1 AND team_id = $2;

-- ExpireApprovalRequests is swept by the same worker that times operations out.
-- name: ExpireApprovalRequests :execrows
UPDATE approval_requests
SET status = 'expired', updated_at = now()
WHERE status IN ('pending', 'approved') AND expires_at <= now();
